    "why": "주가순자산비율은 $$\\text{주가순자산비율}=\\frac{\\text{시가총액}}{\\text{순자산}}$$ 로 볼 수 있어요. 설명을 위해 순자산이 100억 원인데 시가총액이 22억 원이면 0.22배예요(예시 숫자예요). 이익을 비슷하게 내는데도 평가가 낮다면 시장이 **주주환원의 연속성과 실적 변동성**을 걱정하는 거예요. 마침 한국거래소가 22일까지 최근 20거래일 평균 시가총액으로 주가순자산비율을 계산해 11월 2일 첫 저평가 기업 명단을 공표하기로 했고, 22일까지 계획을 공시하면 1년간 공표가 면제돼요(12반기 연속이면 특례 없음). 한화손해보험은 기준일 이틀 전인 20일에 공시했어요. 계리·상품개발 관점에서는 신계약을 팔 때 보험계약마진뿐 아니라 **요구자본까지** 따지는 시대라는 신호예요.",
