    "why": "새 회계기준에서는 보험부채를 매 분기 지금의 금리로 다시 재요. 그래서 부채가 줄었다는 숫자는 회사가 좋아졌다는 뜻이 아닐 수 있어요. 금리가 오르면 보험사가 들고 있는 장기채 값도 떨어져서, 업계의 기타포괄손익누계액은 2023년 말 28조 8,000억 원에서 2024년 말 3,000억 원으로 줄고 자본총계도 103조 3,000억 원에서 82조 1,000억 원으로 줄었어요. 결국 중요한 건 **자산과 부채가 같은 방향으로 움직였는지**예요. 당국이 듀레이션 갭을 경영실태평가 지표에 넣고, 2027년부터 계리가정 보고서를 내게 하려는 것도 같은 이유예요. 뉴스에서 부채 숫자가 크게 바뀌면 **금리 때문인지, 가정 때문인지, 계약 때문인지**를 나눠 묻는 습관을 들이세요.",
